use crate::Analysis;
use crate::analyzers::analyzer::visit_expansion;
use crate::errors::SemanticError;
use crate::semantics::{ComponentInstance, InitSpecifier};
use fpp_ast::{DefComponentInstance, DefModule, SpecInit, SpecTemplateExpand, Visitor, Walkable};
use std::ops::ControlFlow;

/// Check component instance definitions
pub struct CheckComponentInstanceDefs;

impl<'ast> Visitor<'ast> for CheckComponentInstanceDefs {
    type Break = ();
    type State = Analysis;

    /// The members generated by a template expansion are members of the
    /// enclosing module, so analyze them here.
    fn visit_spec_template_expand(
        &self,
        a: &mut Self::State,
        node: &'ast SpecTemplateExpand,
    ) -> ControlFlow<Self::Break> {
        visit_expansion(self, a, node)
    }

    /// Visit translation unit members and module members
    fn visit_def_module(
        &self,
        a: &mut Self::State,
        node: &'ast DefModule,
    ) -> ControlFlow<Self::Break> {
        node.walk(a, self)
    }

    fn visit_def_component_instance(
        &self,
        a: &mut Self::State,
        node: &'ast DefComponentInstance,
    ) -> ControlFlow<Self::Break> {
        let ci = match ComponentInstance::from_def_component_instance(a, node) {
            Ok(Some(ci)) => ci,
            Ok(None) => return ControlFlow::Continue(()),
            Err(err) => {
                err.emit();
                return ControlFlow::Continue(());
            }
        };

        a.component_instance = Some(ci);
        for spec in &node.init_specs {
            self.visit_spec_init(a, spec)?;
        }

        // An init specifier error drops the instance under construction
        if let Some(ci) = a.component_instance.take()
            && let Some(symbol) = a.get_symbol(node)
        {
            a.component_instance_map.insert(symbol, ci);
        }
        ControlFlow::Continue(())
    }

    fn visit_spec_init(&self, a: &mut Self::State, node: &'ast SpecInit) -> ControlFlow<()> {
        let Some(ci) = a.component_instance.take() else {
            return ControlFlow::Continue(());
        };
        match InitSpecifier::from_node(a, node).and_then(|is| ci.add_init_specifier(is)) {
            Ok(ci) => a.component_instance = Some(ci),
            Err(err) => err.emit(),
        }
        ControlFlow::Continue(())
    }
}

impl CheckComponentInstanceDefs {
    /// Ensure that ID ranges do not overlap
    pub fn check_id_ranges(a: &Analysis) {
        // A stable sort, so instances with the same base ID stay in definition
        // order
        let mut instances: Vec<&ComponentInstance> = a.component_instance_map.values().collect();
        instances.sort_by_key(|ci| ci.base_id);

        let mut idx = 0;
        while idx + 1 < instances.len() {
            let i1 = instances[idx];
            let i2 = instances[idx + 1];
            if i2.max_id >= i2.base_id && i1.base_id >= i2.base_id {
                // Error: i2 has a nonempty ID range, and
                // base id for i1 lies in the ID range of i2
                SemanticError::OverlappingIdRanges {
                    base_id1: i1.base_id,
                    name1: i1.get_unqualified_name().to_string(),
                    loc1: i1.get_loc(),
                    base_id2: i2.base_id,
                    max_id2: i2.max_id,
                    name2: i2.get_unqualified_name().to_string(),
                    loc2: i2.get_loc(),
                }
                .emit();
                return;
            } else if i1.max_id < i2.base_id {
                // OK: ID ranges do not overlap; continue checking
                idx += 1;
            } else {
                // Error: Base id for i2 lies in the ID range of i1
                SemanticError::OverlappingIdRanges {
                    base_id1: i2.base_id,
                    name1: i2.get_unqualified_name().to_string(),
                    loc1: i2.get_loc(),
                    base_id2: i1.base_id,
                    max_id2: i1.max_id,
                    name2: i1.get_unqualified_name().to_string(),
                    loc2: i1.get_loc(),
                }
                .emit();
                return;
            }
        }
    }
}
